APXF["za-hemel-en-aarde-valley"] = {"lede": "The lowest of the three Hemel-en-Aarde wards, closest to the sea at Hermanus.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Pinot Noir, Chardonnay, Pinotage, Sauvignon Blanc"]], "sections": [["The place", "<p>Hamilton Russell Vineyards (1975) and Bouchard Finlayson (1989, a venture between Peter Finlayson and Burgundy's Paul Bouchard) established South African Pinot Noir and Chardonnay here; the clay-rich shale soils give wines of structure and minerality.</p><p>Bokkeveld shale with high clay content, stony; cool sea breezes, about 750 mm of rain.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style. This is a ward, the smallest level below a single vineyard.</p>"], ["In the glass", "<p>Burgundian Pinot Noir and Chardonnay; Sauvignon Blanc; Pinotage.</p>"], ["For the exam", "<p>Walker Bay ward closest to the sea; Hamilton Russell Vineyards; Pinot Noir and Chardonnay.</p>"]], "producers": ["Hamilton Russell", "Bouchard Finlayson", "Southern Right", "Whalehaven"], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
APXF["za-herbertsdale"] = {"lede": "A stand-alone ward near the village of Herbertsdale inland from Mossel Bay.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Sauvignon Blanc"]], "sections": [["The place", "<p>Its mild Garden Route climate, with rain through the year, suits white varieties such as Sauvignon Blanc.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style.</p>"], ["In the glass", "<p>Cool-climate Sauvignon Blanc, Chardonnay and Pinot Noir.</p>"], ["For the exam", "<p>WO unit, Cape South Coast region.</p>"]], "producers": [], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
APXF["za-klein-river"] = {"lede": "A ward near Stanford along the Klein River, where award-winning wines (Raka) have emerged.", "facts": [["Category", "WO"], ["Recognized", ""], ["Main grapes", "Sauvignon Blanc, Shiraz, Pinotage"]], "sections": [["The place", "<p>Its cool coastal climate suits Sauvignon Blanc and Bordeaux varieties.</p>"], ["The rules", "<p>A Wine of Origin production area. South Africa's Wine of Origin scheme came into force in 1973 and now operates under the Liquor Products Act of 1989, administered by the Wine and Spirit Board. The law defines a hierarchy of geographical units (such as Western Cape), regions, districts and wards, plus registered single vineyards; overarching units such as Cape Coast and Greater Cape allow blends across regions. A ward must have a clear influence of soil, climate and ecology on the wine, and its name must reflect a real geographic feature. 'Wine of Origin' with an area name guarantees that 100% of the grapes come from that area; a variety or vintage on the label requires 85%. The certification seal on the bottle confirms that the claims were checked and the wine passed tasting. The scheme sets no rules on grapes, yields or style. This is a ward, the smallest level below a single vineyard.</p>"], ["In the glass", "<p>Cool-climate Pinot Noir, Chardonnay and Sauvignon Blanc.</p>"], ["For the exam", "<p>Ward in the Overberg district, Cape South Coast region.</p>"]], "producers": ["Raka"], "sources": [["Wines of South Africa: Wine of Origin scheme", "https://www.wosa.co.za/The-Industry/Wines-Of-Origin/Wine-Of-Origin-scheme"], ["Wine Certification Authority: What we do", "https://wineauthority.org/what-we-do"], ["SAWIS: Wine of Origin Scheme (Liquor Products Act 60 of 1989), updated 2025", "https://www.sawis.co.za/winelaw/download/Wine_of_Origin_Scheme,_updated_05_2025.pdf"]], "checked": "2026-11-14"};
